CREATE TABLE IF NOT EXISTS admin_users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,email TEXT NOT NULL,password_hash TEXT NOT NULL,must_change_password INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO admin_users(username,email,password_hash,must_change_password) VALUES('banklensadmin','sameultekyi@gmail.com','100000:3e89b0b81c95293514774c95489d6d37:bca36f875d40b16b16344c8203d285d076a160559d02cbd36fb8dd575881816c',1);
CREATE TABLE IF NOT EXISTS admin_sessions(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,token_hash TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES admin_users(id));
CREATE TABLE IF NOT EXISTS password_resets(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,token_hash TEXT NOT NULL,expires_at TEXT NOT NULL,used_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES admin_users(id));
CREATE TABLE IF NOT EXISTS countries(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,iso2 TEXT UNIQUE NOT NULL,currency TEXT NOT NULL,regulator_name TEXT NOT NULL,regulator_url TEXT NOT NULL,bank_directory_url TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,discovery_status TEXT NOT NULL DEFAULT 'pending',last_discovered_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO countries(name,iso2,currency,regulator_name,regulator_url,bank_directory_url,enabled,discovery_status) VALUES('Ghana','GH','GHS','Bank of Ghana','https://www.bog.gov.gh','https://www.bog.gov.gh/supervision-regulation/registered-institutions/banks/',1,'ready');
ALTER TABLE banks ADD COLUMN country_id INTEGER REFERENCES countries(id);
ALTER TABLE banks ADD COLUMN website TEXT;
ALTER TABLE banks ADD COLUMN discovery_status TEXT DEFAULT 'verified';
UPDATE banks SET country_id=(SELECT id FROM countries WHERE iso2='GH') WHERE country_id IS NULL;
CREATE TABLE IF NOT EXISTS discovered_links(id INTEGER PRIMARY KEY AUTOINCREMENT,country_id INTEGER NOT NULL,bank_id INTEGER,url TEXT NOT NULL,kind TEXT NOT NULL,title TEXT,content_hash TEXT,status TEXT NOT NULL DEFAULT 'new',discovered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(url),FOREIGN KEY(country_id) REFERENCES countries(id),FOREIGN KEY(bank_id) REFERENCES banks(id));
CREATE TABLE IF NOT EXISTS bank_context(id INTEGER PRIMARY KEY AUTOINCREMENT,bank_id INTEGER NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,url TEXT NOT NULL,publisher TEXT,published_at TEXT,sentiment TEXT,status TEXT NOT NULL DEFAULT 'review',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(url),FOREIGN KEY(bank_id) REFERENCES banks(id));
